<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // Game state
        let player = { x: 0, y: 0 };
        let tiles = {};
        let inventory = { seeds: 10, crops: 0 };
        let day = 0;

        // Game loop
        function gameLoop() {
            requestAnimationFrame(gameLoop);

            // Update game state
            player.x += 0; // No movement
            player.y += 0; // No movement

            // Update tiles
            for (const tile in tiles) {
                const { crop, stage } = tiles[tile];
                if (stage < 3) {
                    tiles[tile].stage++;
                }
            }

            // Update inventory
            if (keyIsDown('p')) {
                const seed = { crop: 'corn', stage: 0 };
                tiles[player.x + ',' + player.y] = seed;
            }

            if (keyIsDown('t')) {
                day++;
            }

            if (keyIsDown('h')) {
                const tile = `${player.x},${player.y}`;
                if (tiles[tile] && tiles[tile].stage === 3) {
                    tiles[tile] = null;
                    inventory.crops++;
                }
            }

            // Draw game
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for (const tile in tiles) {
                const { crop, stage } = tiles[tile];
                if (crop) {
                    drawCrop(ctx, tile, crop, stage);
                }
            }

            // Save game to localStorage
            localStorage.setItem('game', JSON.stringify({ player, tiles, inventory, day }));
        }

        // Draw crop
        function drawCrop(ctx, tile, crop, stage) {
            const { x, y } = tile.split(',');
            const size = 50;
            ctx.fillStyle = crop.color;
            ctx.fillRect(x * size, y * size, size, size);
            ctx.fillStyle = 'black';
            ctx.font = '16px Arial';
            ctx.fillText(`${crop.name} (${stage})`, x * size + 10, y * size + 20);
        }

        // Keydown event handler
        function keyIsDown(key) {
            return window.event.key === key;
        }

        // Load game from localStorage
        if (localStorage.getItem('game')) {
            const savedState = JSON.parse(localStorage.getItem('game'));
            player = savedState.player;
            tiles = savedState.tiles;
            inventory = savedState.inventory;
            day = savedState.day;
        }

        // Start game loop
        gameLoop();
    </script>
</body>
</html>
